    if (next_state_worker_set_3_en) begin
      next_state = WORKER_SET_3;
    end
    if (next_state_worker_wait_1_en) begin
      next_state = WORKER_WAIT_1;
    end
    if (next_state_worker_wait_2_en) begin
      next_state = WORKER_WAIT_2;
    end
  end

  // Unified Multiplexer for LHS: payload
  // Unified combinational mux for: payload
  always_comb begin
    payload = fire_worker_payload;  // Diagnostic retained-view control
    if (payload_fire_worker_payload_en) begin
      payload = fire_worker_payload;
    end
  end

  // Unified Multiplexer for LHS: result
  // Unified flop with mux for: result (register_out assignment)
  always_comb begin
    result_next = result;  // Default value
    if (result_payload_en) begin
      result_next = payload;
    end
  end
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      result <= 4'h0;
    end else begin
      result <= result_next;
    end
  end

  // Unified Multiplexer for LHS: worker_start
  // Unified combinational mux for: worker_start
  always_comb begin
    worker_start = 1'b0;  // Default value
    if (worker_start_fire_worker_en) begin
      worker_start = fire_worker;
    end
  end

  `ifndef SYNTHESIS
  always_comb begin
    assert ($onehot0({next_state_worker_done_4_en, next_state_worker_idle_0_en, next_state_worker_set_3_en, next_state_worker_wait_1_en, next_state_worker_wait_2_en})) else $error("selector multi-value conflict: next_state");
  end
  `endif
endmodule
